VAR
    Overload_Timer : TON;
END_VAR

// Calculate thresholds based on rated current (41.5 A)
// 110% = 45.65 A
// 125% = 51.875 A

// Safe mode and Overload Alarm at 110% (45.65 A) when running
IF Motor_Running AND (Motor_Current >= 45.65) THEN
    Safe_Mode_Active := TRUE;
    Overload_Alarm := TRUE;
END_IF;

// Reset Safe Mode and Overload Alarm on Fault_Reset rising edge (if current is normal)
IF Fault_Reset AND (Motor_Current < 45.65) THEN
    Safe_Mode_Active := FALSE;
    Overload_Alarm := FALSE;
END_IF;

// Shutdown timer at 125% (51.875 A)
Overload_Timer(IN := Motor_Running AND (Motor_Current >= 51.875),
               PT := T#3S);

// Shutdown motor after 3 second delay
IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF;

// Clear Motor_Stop on Fault_Reset rising edge
IF Fault_Reset THEN
    Motor_Stop := FALSE;
END_IF;

